package com.jb.radar;
public class InterceptionTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static Game.EnemyMissile incoming(Game g,int weapon){Game.EnemyMissile m=new Game.EnemyMissile();m.id=101;m.weapon=weapon;m.x=8;m.y=0;m.z=3;m.alt=3000;m.px=8;m.palt=3000;m.samples=3;m.quality=1;m.radarTracked=true;m.hadTrack=true;m.seen=g.elapsed;MissileMotion.aim(m.flight,-m.x,-m.y,Game.terrain(0,0)/1000-m.z);m.pheading=Game.angle(m.flight.vx,m.flight.vy);m.pspeed=m.speed*3600;m.source=GameTest.target(g,0);g.enemyMissiles.add(m);return m;}
 public static void main(String[] args){for(int weapon=0;weapon<5;weapon++){Game g=new Game(4);g.start();g.contacts.clear();Game.EnemyMissile e=incoming(g,weapon);check(g.nextTarget(e.source)==e&&g.nextTarget(e)==e.source,"missile participates in stable contact cycle");g.track(e);GameTest.lock(g,e);check(g.channels()==0&&g.hardLocked(e),"target lock alone consumes no external missile channel");Game.Contact a=GameTest.target(g,1),b=GameTest.target(g,2);GameTest.lock(g,a);GameTest.lock(g,b);check(g.channels()==0&&g.hardLocked(a)&&g.hardLocked(b),"distinct tracked targets can be locked before missiles consume shared capacity");g.launch(e);check(g.shots==1&&g.channels()==1,"launch at missile consumes one shared channel");Game.Missile m=g.missiles.get(0);for(int i=0;i<1000&&m.alive;i++){g.elapsed+=.02;g.sweep=(g.sweep+Game.TAU*.02/g.equipment.radar.sweepSeconds())%Game.TAU;g.fly(m,.02);if(e.alive)g.flyEnemy(e,.02);}check(!e.alive&&g.kills==1&&g.radarHits==0,"moving missile intercepted weapon "+weapon);check(g.channels()==0,"channel freed on intercept");}
 Game g=new Game(1);g.start();Game.EnemyMissile m=incoming(g,4);m.samples=1;check(g.identity(m)==0,"unknown missile");m.samples=8;check(g.identity(m)==0,"tracking history alone proves no allegiance or exact missile type");g.identifyAllegiance(m,Game.Allegiance.HOSTILE,"OBSERVED LAUNCH");check(g.identity(m)==1,"hostile evidence does not imply type recognition");m.recognizedType=g.equipment.enemy[m.weapon].name;check(g.identity(m)==2,"recognized type and hostile evidence combine independently");g.elapsed=9;check(g.identity(m)==2,"stale sensor measurement does not erase recorded identification evidence");Battery.Component cmd=g.battery.parts[Battery.COMMAND];g.explode(cmd.x,cmd.y,400,.01,"COMMAND HIT");check(g.finished&&!g.won,"command destruction defeats battery");g.start();check(g.battery.condition()==100&&g.battery.parts[Battery.COMMAND].alive(),"components reset");System.out.println("PASS: five missile intercepts, channels, cycling, ID transitions and command defeat");}
}
